import {World} from './world.mjs';
import {RunEngine} from './engine.mjs';
import {QuestionClock,MATH_TIMERS,timerLabel} from './timer.mjs';
import {MagicAudio} from './audio.mjs';
import {DEFAULTS,COATS,sanitizeSettings,createQuestion,answerMatches,format,profileKey,profileLabel} from './rules.mjs';
const $=id=>document.getElementById(id),all=s=>[...document.querySelectorAll(s)];
const STORAGE='regenboogrit-v1';let data={settings:{...DEFAULTS},bank:0,bests:{},facts:{},unlocked:['pearl'],review:[],tutorial:false,totalCorrect:0};try{const raw=JSON.parse(localStorage.getItem(STORAGE)||'null');if(raw&&typeof raw==='object')data={...data,...raw};}catch{}
data.settings=sanitizeSettings(data.settings);data.bests=data.bests&&typeof data.bests==='object'?data.bests:{};data.facts=data.facts&&typeof data.facts==='object'?data.facts:{};data.review=Array.isArray(data.review)?data.review:[];data.unlocked=Array.isArray(data.unlocked)?data.unlocked:['pearl'];data.bank=Number.isFinite(data.bank)?Math.max(0,data.bank):0;
let settings=data.settings,world,engine=null,mode='menu',activeModal=null,oldFocus=null,pendingStart=false,question=null,answer='',answerBusy=false,history=[],lastFrame=performance.now(),uiTime=0,tipTimer=0,toastTimer=0,saveFailed=false,hiddenPaused=false,runFacts=[],questionClock=null;
const audio=new MagicAudio();audio.enabled=settings.sound;
function save(){try{data.settings=settings;localStorage.setItem(STORAGE,JSON.stringify(data));}catch{if(!saveFailed){saveFailed=true;toast('Deze browser kan je voortgang niet bewaren.');}}}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3000);}
function tip(title,sub='',duration=4000){$('game-tip').replaceChildren(document.createTextNode(title));if(sub){const s=document.createElement('small');s.textContent=sub;$('game-tip').append(s);}$('game-tip').classList.add('visible');clearTimeout(tipTimer);tipTimer=setTimeout(()=>$('game-tip').classList.remove('visible'),duration);}
function showModal(id){if(!activeModal)oldFocus=document.activeElement;all('.modal').forEach(m=>m.hidden=true);activeModal=id;$(id).hidden=false;$('modal-backdrop').hidden=false;$('menu').inert=true;$('site-header').inert=true;$('hud').inert=true;requestAnimationFrame(()=>{const el=$(id).querySelector('button:not(:disabled)');el?.focus({preventScroll:true});});}
function hideModal(){all('.modal').forEach(m=>m.hidden=true);$('modal-backdrop').hidden=true;activeModal=null;$('menu').inert=false;$('site-header').inert=false;$('hud').inert=false;oldFocus?.focus?.({preventScroll:true});}
function selected(selector,key,value){all(selector).forEach(b=>{const on=b.dataset[key]===value;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on));});}
function renderSettings(){
 selected('[data-mode]','mode',settings.mode);selected('[data-pace]','pace',settings.pace);const target=$('mode-options');
 if(settings.mode==='starter')target.innerHTML='<div class="starter-note"><span class="note-icon">✿</span><span><b>Een fijne start voor begin groep 5</b><small>Tafels 1 t/m 5 · beide getallen maximaal 5<br>Bijvoorbeeld 2 × 3 en 3 × 5. Jij kiest wanneer je verder gaat.</small></span></div>';
 if(settings.mode==='tables'){target.innerHTML='<div class="chips" id="table-chips"></div><p class="option-label">Hoe ver binnen elke tafel?</p><div class="chips" id="factor-chips"></div><p class="option-help">Begin met 1–5. Kies later zelf 1–10 om verder te oefenen.</p>';for(let i=1;i<=10;i++){const b=document.createElement('button');b.textContent=i;b.className=settings.tables.includes(i)?'selected':'';b.setAttribute('aria-label','Tafel van '+i);b.setAttribute('aria-pressed',String(settings.tables.includes(i)));b.onclick=()=>{if(settings.tables.includes(i)){if(settings.tables.length===1){toast('Kies minstens één tafel.');return;}settings.tables=settings.tables.filter(n=>n!==i);}else settings.tables=[...settings.tables,i].sort((a,b)=>a-b);save();renderSettings();};$('table-chips').append(b);}for(const n of [5,10]){const b=document.createElement('button');b.textContent='× 1 t/m '+n;b.className=settings.factorMax===n?'selected':'';b.setAttribute('aria-pressed',String(settings.factorMax===n));b.onclick=()=>{settings.factorMax=n;save();renderSettings();};$('factor-chips').append(b);}}
 if(settings.mode==='arithmetic'){target.innerHTML='<div class="chips arithmetic-presets" id="arithmetic-presets"></div><p class="option-label">Of kies zelf het bereik en de sommen:</p><div class="chips" id="range-chips"></div><div class="chips" id="operation-chips" style="margin-top:8px"></div>';for(const [grade,range]of [[3,20],[4,100]]){const b=document.createElement('button');b.textContent='Groep '+grade+' · plus onder '+range;b.className=settings.range===range&&settings.operation==='plus'?'selected':'';b.setAttribute('aria-pressed',String(settings.range===range&&settings.operation==='plus'));b.onclick=()=>{settings.range=range;settings.operation='plus';save();renderSettings();};$('arithmetic-presets').append(b);}for(const n of [20,50,100]){const b=document.createElement('button');b.textContent='Onder '+n;b.className=settings.range===n?'selected':'';b.setAttribute('aria-pressed',String(settings.range===n));b.onclick=()=>{settings.range=n;save();renderSettings();};$('range-chips').append(b);}for(const [id,label]of [['plus','Alleen +'],['minus','Alleen −'],['mix','Door elkaar']]){const b=document.createElement('button');b.textContent=label;b.className=settings.operation===id?'selected':'';b.setAttribute('aria-pressed',String(settings.operation===id));b.onclick=()=>{settings.operation=id;save();renderSettings();};$('operation-chips').append(b);}}
 if(settings.mode==='group'){target.innerHTML='<div class="chips" id="group-chips"></div><p class="option-help" id="group-help"></p>';for(let n=3;n<=8;n++){const b=document.createElement('button');b.textContent='Groep '+n;b.className=settings.group===n?'selected':'';b.setAttribute('aria-pressed',String(settings.group===n));b.onclick=()=>{settings.group=n;save();renderSettings();};$('group-chips').append(b);}const text={3:'Plus en min onder 20. Vertrouwde kleine stapjes.',4:'Plus en min onder 100, met kleine tafels van 1, 2, 5 en 10.',5:'Begin groep 5: kleine tafels tot 5 × 5, plus en min onder 100 en kleine deelsommen.',6:'Tafels tot 10, grotere getallen, delen en eenvoudige breuken.',7:'Tafels, kommagetallen en eenvoudige percentages.',8:'Kommagetallen, breuken en percentages door elkaar.'};$('group-help').textContent=text[settings.group];}
 renderTimerOptions();$('bank-count').textContent=data.bank;renderSound();
}
function renderTimerOptions(){const root=$('timer-options');root.replaceChildren();for(const choice of MATH_TIMERS){const b=document.createElement('button');b.className=choice.seconds===settings.mathSeconds?'selected':'';b.setAttribute('aria-pressed',String(choice.seconds===settings.mathSeconds));b.setAttribute('aria-label',choice.label+' · '+choice.time);const label=document.createElement('b'),time=document.createElement('small');label.textContent=choice.label;time.textContent=choice.time;b.append(label,time);b.onclick=()=>{settings.mathSeconds=choice.seconds;save();renderTimerOptions();};root.append(b);}$('timer-help').textContent=settings.mathSeconds?'Per som '+settings.mathSeconds+' seconden. Tijd op? Wel verder, geen boost. Een reddingssom stopt dan de rit.':'Alle tijd om te oefenen. De race wacht tijdens iedere som.';}
function renderSound(){$('sound-button').setAttribute('aria-pressed',String(settings.sound));$('sound-button').setAttribute('aria-label',settings.sound?'Geluid uitzetten':'Geluid aanzetten');}
all('[data-mode]').forEach(b=>b.onclick=()=>{settings.mode=b.dataset.mode;save();renderSettings();});
all('[data-pace]').forEach(b=>b.onclick=()=>{settings.pace=b.dataset.pace;save();renderSettings();});
$('sound-button').onclick=()=>{settings.sound=!settings.sound;audio.enabled=settings.sound;audio.unlock();if(settings.sound)audio.play('coin');save();renderSound();};
$('play-button').onclick=()=>{audio.unlock();if(!world)return;if(!data.tutorial){pendingStart=true;showModal('help-modal');}else startRun();};
$('help-button').onclick=()=>{pendingStart=false;showModal('help-modal');};
$('help-done').onclick=()=>{hideModal();if(pendingStart){data.tutorial=true;save();pendingStart=false;startRun();}};
all('.close-modal').forEach(b=>b.onclick=()=>{pendingStart=false;hideModal();});
document.querySelector('.brand').onclick=e=>{e.preventDefault();if(mode==='menu')window.scrollTo({top:0,behavior:'smooth'});};
function startRun(){questionClock=null;hideModal();window.scrollTo(0,0);engine=new RunEngine(settings);mode='game';runFacts=[];world.reset();world.setCoat(COATS.find(c=>c.id===settings.coat).color);$('menu').hidden=true;$('hud').hidden=false;document.body.classList.add('playing');document.body.classList.remove('boosting');$('game-tip').classList.remove('visible');updateHUD();processEvents();}
function home(){questionClock=null;hideModal();engine=null;mode='menu';$('menu').hidden=false;$('hud').hidden=true;$('countdown').hidden=true;document.body.classList.remove('playing','boosting');world.reset();world.addObstacle('cloud',-1,-12);world.addObstacle('arch',1,-25);renderSettings();}
$('pause-button').onclick=()=>{engine?.pause();processEvents();};
$('resume-button').onclick=()=>{hideModal();engine?.resume();processEvents();};
$('quit-button').onclick=()=>{hideModal();engine?.finish('stop');processEvents();};
$('again-button').onclick=startRun;$('home-button').onclick=home;
function nextQuestion(){const key=profileKey(settings);data.review.forEach(q=>{if(q.profile===key)q.wait--;});const idx=data.review.findIndex(q=>q.profile===key&&q.wait<=0);let q;if(idx>=0){q=data.review.splice(idx,1)[0].question;}else{for(let i=0;i<10;i++){q=createQuestion(settings);if(!history.slice(-2).includes(q.key))break;}}history.push(q.key);if(history.length>8)history.shift();return q;}
function openQuestion(kind){question=nextQuestion();answer='';answerBusy=false;$('math-modal').classList.remove('success');$('question').textContent=question.prompt;$('answer-display').textContent='?';$('math-feedback').textContent=kind==='rescue'?'Eén goed antwoord en je mag weer verder.':'Welk getal hoort op de plek van het vraagteken?';$('math-visual').hidden=true;$('math-visual').replaceChildren();$('math-eyebrow').textContent=kind==='rescue'?'EEN NIEUW KANSJE · '+(engine.usedRescues+1)+' VAN 3':'EEN BEETJE REKENMAGIE';$('math-title').textContent=kind==='rescue'?'Help je eenhoorn verder.':'Tover een boost!';$('math-subtitle').textContent=settings.mathSeconds?'De wereld wacht. Je hebt '+settings.mathSeconds+' seconden voor deze som.':'De wereld wacht even. Neem rustig je tijd.';$('math-skip').textContent=kind==='rescue'?'Deze rit afronden':'Deze som samen bekijken';$('answer-button').disabled=false;$('math-skip').disabled=false;showModal('math-modal');document.body.classList.remove('boosting');questionClock=new QuestionClock(settings.mathSeconds,performance.now());if(document.hidden)questionClock.pause(performance.now());renderQuestionClock();}
function renderQuestionClock(){const clock=questionClock;const visible=!!clock?.limit;$('math-timer').hidden=!visible;if(!visible)return;const remaining=Math.max(0,Math.ceil(clock.remaining));$('math-timer-label').textContent=clock.expired?'De tijd is op':(clock.paused?'Even pauze · ':'Nog ')+remaining+' seconden';const percent=Math.max(0,clock.remaining/clock.limit*100);$('math-timer-fill').style.width=percent+'%';const track=$('math-timer').querySelector('.timer-track');track.setAttribute('aria-valuenow',String(Math.ceil(percent)));$('math-timer').classList.toggle('almost-up',clock.remaining<=5&&!clock.expired);}
function checkQuestionClock(now=performance.now()){if(activeModal!=='math-modal'||!questionClock||answerBusy)return false;const expiredNow=questionClock.update(now);if(expiredNow){engine.timeOut();processEvents();}renderQuestionClock();return expiredNow||questionClock.expired;}
function stopQuestionClock(){questionClock?.stop(questionClock.last);renderQuestionClock();}
function questionTimedOut(kind){answerBusy=true;$('answer-button').disabled=true;$('math-skip').disabled=true;recordQuestion(false,false);$('answer-display').textContent=format(question.answer);$('math-feedback').textContent=question.prompt+' = '+format(question.answer)+'. '+(kind==='rescue'?'De tijd is op. Een nieuw avontuur staat op je te wachten.':'De tijd is op. Je hobbelt verder zonder boost; deze oefenen we later nog eens.');renderQuestionClock();setTimeout(()=>{questionClock=null;hideModal();engine.completeTimeout();processEvents();if(document.hidden){engine.pause();processEvents();}},2400);}
function inputDigit(d){if(activeModal!=='math-modal'||answerBusy||checkQuestionClock())return;if(d==='back')answer=answer.slice(0,-1);else if(d===','){if(!answer.includes(',')&&answer.length)answer+=',';}else if(answer.replace(',','').length<6)answer=(answer==='0'?d:answer+d);$('answer-display').textContent=answer||'?';}
all('[data-digit]').forEach(b=>b.onclick=()=>inputDigit(b.dataset.digit));
function recordQuestion(correct,independent){const key=question.key;const fact=data.facts[key]||{good:0,help:0,wrong:0,table:question.kind==='×'?question.b:null};if(correct){if(independent){fact.good++;data.totalCorrect++;runFacts.push(question.prompt);}else fact.help++;}else fact.wrong++;data.facts[key]=fact;if(!correct&&!data.review.some(q=>q.profile===profileKey(settings)&&q.question.key===key)){data.review.push({profile:profileKey(settings),question,wait:3});if(data.review.length>40)data.review.shift();}save();}
function revealHint(){const visual=$('math-visual');visual.replaceChildren();if(question.kind==='×'&&question.a<=5&&question.b<=5){for(let i=0;i<question.a;i++){const group=document.createElement('span');group.textContent='✦'.repeat(question.b);visual.append(group);}visual.hidden=false;}}
function submitAnswer(){if(activeModal!=='math-modal'||answerBusy||!answer||checkQuestionClock())return;audio.unlock();const correct=answerMatches(answer,question.answer);const independent=!engine.questionAssisted;recordQuestion(correct,independent);
 if(correct){stopQuestionClock();answerBusy=true;$('answer-button').disabled=true;$('math-skip').disabled=true;$('math-feedback').textContent=independent?'Ja! '+question.prompt+' = '+format(question.answer)+'. Jij kunt dit!':'Goed geoefend! '+question.prompt+' = '+format(question.answer)+'.';$('math-modal').classList.add('success');audio.play('correct');setTimeout(()=>{hideModal();engine.answer(true);processEvents();},850);}
 else if(engine.mathKind==='rescue'){stopQuestionClock();answerBusy=true;$('answer-button').disabled=true;$('math-skip').disabled=true;$('math-feedback').textContent=question.prompt+' = '+format(question.answer)+'. Volgende keer proberen we het weer!';setTimeout(()=>{hideModal();engine.answer(false);processEvents();},1800);}
 else{engine.answer(false);$('math-feedback').textContent='Bijna! '+question.hint;revealHint();answer='';$('answer-display').textContent='?';$('math-skip').textContent='Bekijk het antwoord en hobbel verder';}
}
$('answer-button').onclick=submitAnswer;
$('math-skip').onclick=()=>{if(answerBusy||checkQuestionClock())return;if(engine.mathKind==='rescue'){stopQuestionClock();hideModal();engine.skip();processEvents();return;}if(!engine.questionAssisted){engine.questionAssisted=true;recordQuestion(false,false);$('math-feedback').textContent=question.hint;revealHint();$('math-skip').textContent='Bekijk het antwoord en hobbel verder';return;}stopQuestionClock();answerBusy=true;$('answer-button').disabled=true;$('math-skip').disabled=true;$('answer-display').textContent=format(question.answer);$('math-feedback').textContent=question.prompt+' = '+format(question.answer)+'. Die oefenen we straks nog een keer.';setTimeout(()=>{hideModal();engine.skip();processEvents();},2000);};
function endRun(result){questionClock=null;document.body.classList.remove('boosting');$('countdown').hidden=true;$('game-tip').classList.remove('visible');clearTimeout(tipTimer);const key=profileKey(settings),previous=data.bests[key]||0;const record=result.distance>previous;data.bests[key]=Math.max(previous,result.distance);data.bank+=result.stars;save();$('end-distance').textContent=result.distance.toLocaleString('nl-NL');$('end-stars').textContent=result.stars;$('end-correct').textContent=result.independent;$('end-eyebrow').textContent=record?'EEN NIEUW PERSOONLIJK RECORD':'WAT EEN AVONTUUR';$('end-title').textContent=result.independent?'Jij hebt geschitterd!':'Mooi gehobbeld!';const reason={timeout:'De tijd voor je reddingssom was op. Je sterren zijn bewaard; probeer gerust opnieuw.',quick:'Dat was snel na je redding. Deze rit is klaar; je sterren blijven van jou.',rescues:'Je hebt alle drie je reddingen gebruikt. Tijd voor een nieuw avontuur!',answer:'Een lastig sommetje hoort erbij. Je mag het altijd opnieuw proberen.',stop:'Je eenhoorn heeft even pauze. Je sterren zijn bewaard.'};$('end-reason').textContent=reason[result.reason];$('end-learning').textContent=runFacts.length?'Zelf opgelost: '+[...new Set(runFacts)].slice(-3).join(' · ')+'. Een stapje vooruit!':'Ieder avontuur maakt je handiger. Probeer gerust nog een keer.';$('end-best').textContent='Beste rit: '+data.bests[key].toLocaleString('nl-NL')+' m · '+profileLabel(settings)+' · '+timerLabel(settings.mathSeconds);showModal('end-modal');audio.play('end');}
function processEvents(){if(!engine)return;for(const e of engine.drain()){switch(e.type){
 case 'countdown':$('countdown').hidden=false;$('countdown').textContent=e.value;audio.play('countdown');break;
 case 'started':$('countdown').hidden=true;audio.play('start');if(engine.elapsed<1)tip('Je eenhoorn loopt vanzelf','Veeg ← → om van baan te wisselen. ↑ spring · ↓ buk',5500);break;
 case 'move':world.move(e.delta);break;
 case 'obstacle':{const o=world.addObstacle(e.kind,e.lane,e.z);o.id=e.id;if(engine.elapsed<20){const messages={cloud:['Wolkje in zicht!','Spring erover of kies een andere baan.'],arch:['Een elfjesboog!','Buk eronder of ga erlangs.'],dragon:['Een slapende draak','Kies een vrije baan.']};tip(...messages[e.kind],3300);}break;}
 case 'coin':{const c=world.addCoin(e.lane,e.z);world.coins[world.coins.length-1].id=e.id;break;}
 case 'collected':{const c=world.coins.find(c=>c.id===e.id);if(c){world.scene.remove(c.group);world.coins=world.coins.filter(o=>o!==c);}audio.play('coin');break;}
 case 'clear':world.clearAhead(1000);break;
 case 'gate':world.addGate(e.z);tip('Een magische rekenpoort!','Zo meteen krijg je rustig de tijd voor een som.',3500);break;
 case 'math':$('countdown').hidden=true;openQuestion(e.kind);break;
 case 'mathTimeout':questionTimedOut(e.kind);break;
 case 'boost':document.body.classList.add('boosting');audio.play('boost');tip('Regenboogboost! ✦','+'+e.reward+' sterren · Je vliegt veilig over alles heen!',3000);break;
 case 'boostEnd':document.body.classList.remove('boosting');tip('En weer rustig landen…','Jij stuurt weer. Op naar de volgende poort!',2000);break;
 case 'rescued':toast('Daar gaan we weer! Nog '+(3-engine.usedRescues)+' reddingen.');break;
 case 'skipped':tip('Goed geoefend!','We proberen die som later nog een keer.',2200);break;
 case 'jump':audio.play('jump');break;case 'duck':audio.play('duck');break;
 case 'paused':$('countdown').hidden=true;showModal('pause-modal');break;
 case 'end':endRun(e.result);break;
 }}}
function updateHUD(){if(!engine)return;$('distance').textContent=Math.floor(engine.distance).toLocaleString('nl-NL');$('run-stars').textContent=engine.stars;$('lives').textContent='♡ '.repeat(3-engine.usedRescues)+'· '.repeat(engine.usedRescues);$('lives').setAttribute('aria-label',(3-engine.usedRescues)+' reddingen over');$('world-name').textContent=world.worldName;const remaining=engine.nextGate-engine.elapsed;$('magic-fill').style.width=(engine.mode==='boost'?100:Math.max(0,Math.min(100,(1-remaining/35)*100)))+'%';$('magic-label').textContent=engine.mode==='boost'?'Regenboogboost!':engine.lastRescue!==null&&engine.elapsed-engine.lastRescue<5?'Rustig verder na je redding':'Magische rekenpoort';}
function control(action){if(activeModal)return;engine?.action(action);processEvents();}
all('[data-control]').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();control(b.dataset.control);}));
let pointer=null;
$('world').addEventListener('pointerdown',e=>{if(mode==='game'&&!activeModal){pointer={x:e.clientX,y:e.clientY,id:e.pointerId};$('world').setPointerCapture(e.pointerId);}});
$('world').addEventListener('pointerup',e=>{if(!pointer||pointer.id!==e.pointerId)return;const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;pointer=null;if(Math.max(Math.abs(dx),Math.abs(dy))<22)return;control(Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'duck':'jump');});
$('world').addEventListener('pointercancel',()=>pointer=null);
addEventListener('keydown',e=>{
 if(activeModal&&e.key==='Tab'){const focusable=[...$(activeModal).querySelectorAll('button:not([disabled])')].filter(b=>!b.hidden);const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}return;}
 if(activeModal==='math-modal'){if(/^\d$/.test(e.key)){e.preventDefault();inputDigit(e.key);}else if(e.key===','||e.key==='.'){e.preventDefault();inputDigit(',');}else if(e.key==='Backspace'){e.preventDefault();inputDigit('back');}else if(e.key==='Enter'){e.preventDefault();submitAnswer();}return;}
 if(e.key==='Escape'){if(activeModal==='pause-modal'){$('resume-button').click();}else if(activeModal&&mode==='menu'){pendingStart=false;hideModal();}else if(!activeModal&&engine){engine.pause();processEvents();}return;}
 if(activeModal)return;
 const action={ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right',ArrowUp:'jump',' ':'jump',w:'jump',ArrowDown:'duck',s:'duck'}[e.key];if(action&&mode==='game'){e.preventDefault();if(!e.repeat)control(action);}
});
document.addEventListener('visibilitychange',()=>{const now=performance.now();if(document.hidden&&engine){if(activeModal==='math-modal'&&questionClock&&!answerBusy){if(questionClock.pause(now)){engine.timeOut();processEvents();}renderQuestionClock();}if(['run','boost','countdown'].includes(engine.mode)){engine.pause();processEvents();}hiddenPaused=true;}else{lastFrame=now;if(hiddenPaused&&engine&&['run','boost','countdown'].includes(engine.mode)){engine.pause();processEvents();}questionClock?.resume(now);hiddenPaused=false;renderQuestionClock();}});
function collection(){renderCollection();showModal('collection-modal');}
$('collection-button').onclick=collection;
function renderCollection(){$('collection-stars').textContent=data.bank;const root=$('coat-options');root.replaceChildren();for(const coat of COATS){const unlocked=data.unlocked.includes(coat.id),b=document.createElement('button');b.className='coat-option'+(settings.coat===coat.id?' selected':'');b.setAttribute('aria-label',coat.name+(unlocked?' kiezen':' vrijspelen voor '+coat.cost+' sterren'));b.innerHTML='<span class="coat-swatch"></span><b></b><small></small>';b.querySelector('.coat-swatch').style.background=coat.color;b.querySelector('b').textContent=coat.name;b.querySelector('small').textContent=settings.coat===coat.id?'Jouw eenhoorn':unlocked?'Kiezen':coat.cost+' sterren';b.onclick=()=>{if(!unlocked){if(data.bank<coat.cost){toast('Nog '+(coat.cost-data.bank)+' sterren voor '+coat.name+'.');return;}data.bank-=coat.cost;data.unlocked.push(coat.id);}settings.coat=coat.id;world.setCoat(coat.color);save();renderCollection();$('bank-count').textContent=data.bank;audio.play('correct');};root.append(b);}$('progress-summary').textContent=data.totalCorrect?data.totalCorrect+' sommen zelfstandig opgelost. Elke ster hieronder is 5 goede antwoorden binnen die tafel.':'Ieder sommetje is een stapje vooruit.';$('table-progress').replaceChildren();for(let n=1;n<=10;n++){const good=Object.values(data.facts).filter(f=>f.table===n).reduce((a,f)=>a+(f.good||0),0);const s=document.createElement('span');s.textContent=n+' × '+(good>=5?'★'.repeat(Math.min(3,Math.floor(good/5))):'☆');s.className=good>=5?'progress-done':'';s.title=good+' goede antwoorden in tafel '+n;$('table-progress').append(s);}}
function frame(now){const dt=Math.min((now-lastFrame)/1000,.05);lastFrame=now;if(!hiddenPaused){checkQuestionClock(now);if(engine){engine.step(dt);processEvents();}const state=engine?{mode:engine.mode,elapsed:engine.elapsed,x:engine.x,jump:engine.jump,duck:engine.duckTime>0,shield:engine.shield,lean:engine.lane*2.8-engine.x}:{mode:'menu'};world.update(dt,state);uiTime+=dt;if(uiTime>.12){updateHUD();uiTime=0;}}requestAnimationFrame(frame);}
function fatal(error){$('loading').hidden=true;$('error-panel').hidden=false;$('error-message').textContent='Je browser kon de 3D-wereld niet openen. Probeer een recente versie van Safari, Chrome of Edge met WebGL ingeschakeld.';console.error(error);}
try{renderSettings();world=new World($('world'));world.setCoat(COATS.find(c=>c.id===settings.coat).color);world.addObstacle('cloud',-1,-12);world.addObstacle('arch',1,-25);$('loading').hidden=true;requestAnimationFrame(frame);}catch(error){fatal(error);}
